class ReplayableGen:
    def __init__(self, gen_fn, *args, **kwargs):
        self._gen_fn = gen_fn
        self._args = args
        self._kwargs = kwargs
        self._cache = []
        self._gen = gen_fn(*args, **kwargs)
        self._done = False

    def __iter__(self):
        idx = 0
        while True:
            if idx < len(self._cache):
                yield self._cache[idx]
            elif self._done:
                return
            else:
                try:
                    val = next(self._gen)
                    self._cache.append(val)
                    yield val
                except StopIteration:
                    self._done = True
                    return
            idx += 1

def expensive_gen(n):
    for i in range(n):
        print(f"  [computing {i}]")
        yield i * i

rg = ReplayableGen(expensive_gen, 4)

print("First pass (computes each value):")
for v in rg:
    print(f"  got {v}")

print()
print("Second pass (reads from cache, no recomputation):")
for v in rg:
    print(f"  got {v}")

